// Regenerates src/ui/vendor-assets.ts from scripts/vendor-entry.js.
//
// Run this after bumping the music-metadata-browser version in
// package.json (devDependencies) -- `npm install` first, then:
//   node scripts/build-vendor-bundle.mjs
//
// The output is served same-origin at GET /vendor/music-metadata.js (see
// src/index.ts) instead of the client pulling it from esm.sh at runtime.
// That route is cached for a year as immutable, so the bundle also exports
// a content-hash version appended as ?v=... wherever it's imported --
// otherwise a rebuilt bundle would sit behind old cached bytes at the same
// URL indefinitely. See the longer version of this comment in
// scripts/build-icons.mjs, which hit exactly this bug.
import { build } from 'esbuild';
import { createHash } from 'node:crypto';
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const entry = path.join(__dirname, 'vendor-entry.js');
const outFile = path.join(__dirname, '..', 'src', 'ui', 'vendor-assets.ts');

const result = await build({
  entryPoints: [entry],
  bundle: true,
  format: 'esm',
  minify: true,
  target: 'es2020',
  write: false,
});

const code = result.outputFiles[0].contents;
const b64 = Buffer.from(code).toString('base64');
const version = createHash('sha256').update(code).digest('hex').slice(0, 10);
const lineLength = 120;
const lines = [];
for (let i = 0; i < b64.length; i += lineLength) lines.push(b64.slice(i, i + lineLength));

const source = `// AUTO-GENERATED by scripts/build-vendor-bundle.mjs -- do not edit by hand.
// Base64-encoded, minified ESM bundle exposing music-metadata-browser's
// parseBlob(), the only export src/ui/client.ts uses. Regenerate with:
//   node scripts/build-vendor-bundle.mjs
export const MUSIC_METADATA_BUNDLE_B64 =
${lines.map((l, i) => `  '${l}'${i < lines.length - 1 ? ' +' : ';'}`).join('\n')}

// Content hash of the bundle above -- append as ?v=\${VENDOR_ASSET_VERSION}
// to /vendor/music-metadata.js so a rebuilt bundle isn't stuck behind a
// year-long immutable cache at the same URL.
export const VENDOR_ASSET_VERSION = "${version}";
`;

await writeFile(outFile, source);
console.log(`Wrote ${outFile} (${code.length} bytes bundled, ${b64.length} bytes base64, version ${version})`);
